function fxCategory(raw){
  raw=Number(raw);
  if(raw<=5)return "reverb";
  if(raw<=8)return "early";
  if(raw===9||raw===10)return "delay";
  if(raw>=11&&raw<=14)return "chorus";
  if(raw===15||raw===16)return "phaser";
  if(raw===17||raw===18)return "trem";
  if(raw===19)return "eq";
  if(raw===20||raw===21)return "drive";
  if(raw===22)return "exciter";
  if(raw===23)return "ensemble";
  if(raw===24)return "rotary";
  if(raw>=25&&raw<=32)return "combo";
  return "through";
}
function decodeFxParams(rawType,p){
  const t=Number(rawType), r=(p||[]).map(x=>Number(x)||0), out=[];
  if(t>=0&&t<=5){
    out.push("Reverb "+(0.2+r[0]*0.1).toFixed(1)+" s","High Damp "+r[2]+"%","Pre-delay "+r[3]+" ms","E/R Level "+r[4]+"%","EQ High "+signed(s8(r[6]))+" dB","EQ Low "+signed(s8(r[7]))+" dB");
  }else if(t>=6&&t<=8){
    out.push("E/R Time "+(100+r[0]*10)+" ms","Pre-delay "+r[1]+" ms","EQ High "+signed(s8(r[6]))+" dB","EQ Low "+signed(s8(r[7]))+" dB");
  }else if(t===9||t===10){
    out.push("Delay L "+(r[0]+256*r[1])+" ms","Delay R "+(r[4]+256*r[5])+" ms","Feedback "+signed(s8(r[2]))+"%","High Damp "+r[3]+"%","EQ High "+signed(s8(r[6]))+" dB","EQ Low "+signed(s8(r[7]))+" dB");
  }else if(t>=11&&t<=14){
    out.push("Depth "+r[0]+"%","Speed "+effectSpeed(r[1]).toFixed(2)+" Hz","Wave "+((r[2]&1)?"TRI":"SIN"),"Phase "+((r[2]&2)?"180°":"0°"),"Feedback "+signed(s8(r[3]))+"%","Delay "+r[4]+" ms","EQ High "+signed(s8(r[6]))+" dB","EQ Low "+signed(s8(r[7]))+" dB");
  }else if(t===15||t===16){
    out.push("Depth "+r[0]+"%","Speed "+effectSpeed(r[1]).toFixed(2)+" Hz","Wave "+((r[2]&1)?"TRI":"SIN"),"Feedback "+signed(s8(r[3]))+"%","Manual "+r[4]);
  }else if(t===17||t===18){
    out.push("Depth "+r[0]+"%","Speed "+effectSpeed(r[1]).toFixed(2)+" Hz","Wave "+((r[2]&1)?"TRI":"SIN"),"Shape "+signed(s8(r[3])),"EQ High "+signed(s8(r[6]))+" dB","EQ Low "+signed(s8(r[7]))+" dB");
  }else if(t===19){
    const mid=[.5,1,2][clamp(r[0],0,2)],lo=[.25,.5,1][clamp(r[4],0,2)],hi=[1,2,4][clamp(r[5],0,2)];
    out.push("Mid "+mid+" kHz / "+signed(s8(r[1]))+" dB","Low "+lo+" kHz / "+signed(s8(r[7]))+" dB","High "+hi+" kHz / "+signed(s8(r[6]))+" dB");
  }else if(t===20){out.push("Drive "+r[2]+"%","Level "+r[3]+"%","Mid Gain "+signed(s8(r[1]))+" dB","High "+signed(s8(r[6]))+" dB","Low "+signed(s8(r[7]))+" dB");
  }else if(t===21){out.push("Distortion "+r[2]+"%","Level "+r[3]+"%","Low EQ "+signed(s8(r[7]))+" dB");
  }else if(t===22){out.push("Blend "+signed(s8(r[0]))+"%","Emphatic Point "+(r[1]+1),"High "+signed(s8(r[6]))+" dB","Low "+signed(s8(r[7]))+" dB");
  }else if(t===23){out.push("Depth "+r[0]+"%","High "+signed(s8(r[6]))+" dB","Low "+signed(s8(r[7]))+" dB");
  }else if(t===24){out.push("Depth "+r[0]+"%","Speed Ratio "+signed(s8(r[2])),"Shape "+signed(s8(r[7])));
  }else if(t>=25&&t<=32){
    out.push("Delay "+(r[0]+256*r[1])+" ms","Delay FB "+signed(s8(r[2]))+"%","High Damp "+r[3]+"%");
    if(t===25||t===26)out.push((t===25?"Hall":"Room")+" "+(0.2+r[4]*0.1).toFixed(1)+" s","Pre-delay "+r[5]+" ms","Damp "+r[6]+"%");
    else if(t===27)out.push("E/R Time "+(100+r[4]*10)+" ms","Pre-delay "+r[5]+" ms");
    else if(t===28)out.push("Delay 2 "+(r[4]+256*r[5])+" ms","FB2 "+signed(s8(r[6]))+"%","Damp2 "+r[7]+"%");
    else out.push("Mod depth "+r[4]+"%","Mod speed "+effectSpeed(r[5]).toFixed(2)+" Hz","P6 "+r[6],"P7 "+s8(r[7]));
  }else out.push("Through / no processing");
  return out;
}
function deriveFxModel(fx){
  // Keep the legacy model controls informative, but audio is now built from
  // the actual two-unit factory routing and the effect-specific raw bytes.
  params.chorusMix=params.delayMix=params.reverbMix=0;params.eqLow=params.eqHigh=0;
  const items=[{type:fx.type1,bal:(fx.balance1L+fx.balance1R)/2,raw:fx.params1},{type:fx.type2,bal:(fx.balance2L+fx.balance2R)/2,raw:fx.params2}];
  for(const e of items){
    const c=fxCategory(e.type),wet=clamp(e.bal,0,100);
    if(c==="reverb"||c==="early"){params.reverbMix=Math.max(params.reverbMix,wet);params.reverbTime=c==="reverb"?.2+e.raw[0]*.1:(.1+e.raw[0]*.01);params.reverbDamp=e.raw[2]||0}
    if(c==="delay"||c==="combo"){params.delayMix=Math.max(params.delayMix,wet);params.delayTime=clamp((e.raw[0]+256*e.raw[1])/1000,.001,1.5);params.delayFeedback=Math.abs(s8(e.raw[2]))}
    if(c==="chorus"||c==="phaser"||c==="ensemble"||c==="rotary"){params.chorusMix=Math.max(params.chorusMix,wet);params.chorusRate=effectSpeed(e.raw[1]||30);params.chorusDepth=e.raw[0]||0}
  }
}


