  bus.connect(dryRefGain).connect(fxMasterSum);bus.connect(factoryFxIn);factoryFxOut.connect(factoryEngineGain).connect(fxMasterSum);
  fxMasterSum.connect(expressionGain).connect(master).connect(limiter).connect(audio.destination);
  bendConst=audio.createConstantSource();bendConst.start();
  rebuildFactoryFx();
  if(immediate){
    master.gain.value=params.masterVolume/100;
    expressionGain.gain.value=params.expression/100;
    dryRefGain.gain.value=dryReference?1:0;
    factoryEngineGain.gain.value=dryReference?0:1;
    bendConst.offset.value=(window._bendCents||0)+(window._aftertouchCents||0);
  }else applyGlobals();
  if(ui){
    document.getElementById("audioBtn").textContent="AUDIO ✓";
    setStatus("Audio ready — v12 level fix + ROM VDF + DWGS reconstruction + FX balance active.");
  }
