  let state=(0x9e3779b9^(seed*2654435761))>>>0;
  const rnd=()=>{state=(1664525*state+1013904223)>>>0;return state/4294967296*2-1};
  const q=x=>Math.round(clamp(x,-1,1)*32767)/32767;
