function paramChanged(id){
  if(loadingControls)return;
  if(oscParamIds.has(id)){syncParamsToOsc();renderZoneTable();renderProgramData();refreshLCD()}
  if(globalProgIds.has(id)&&programState){syncGlobalProgramParams();renderProgramData();if(["programMode","programAssign","programHold"].includes(id))updateOscEditState()}
  if(programState&&["fxType1","fxType2","fxBal1L","fxBal1R","fxBal2L","fxBal2R","fxRouting"].includes(id)){deriveFxModel(programState.fx);loadingControls=true;refreshAllControls();loadingControls=false;if(audio){rebuildFactoryFx();applyGlobals()}}
  if(["masterVolume","expression"].includes(id))applyGlobals();
  if(id==="joyPitchBend"){}
}
